'use strict';
const fs=require('node:fs/promises'),path=require('node:path');
const {contained,atomicJSON,readJSON}=require('./core.cjs');
function patchEssential(source){const lines=source.split(/\r?\n/);let start=lines.findIndex(s=>s.trim()==='[general.experience]');if(start<0)return source.replace(/\s*$/,'')+'\n\n[general.experience]\nessential_menu_layout = 2\n';let end=start+1;while(end<lines.length&&!/^\s*\[/.test(lines[end]))end++;for(let i=start+1;i<end;i++)if(/^\s*essential_menu_layout\s*=/.test(lines[i])){lines[i]=lines[i].replace(/(essential_menu_layout\s*=\s*)\d+/,'$12');return lines.join('\n');}lines.splice(end,0,'essential_menu_layout = 2');return lines.join('\n');}
async function sync(directory,preset){const marker=await contained(directory,'.boralances/title-integration-1.8.3.json');if(await fs.stat(marker).catch(()=>null))return;const patches=[['config/modmenu.json',old=>JSON.stringify({...JSON.parse(old||'{}'),mods_button_style:'classic',modify_title_screen:true},null,2)+'\n']];if(preset.features?.some(f=>f.id==='essential'))patches.push(['essential/config.toml',patchEssential]);for(const [name,patch]of patches){const file=await contained(directory,name),old=await fs.readFile(file,'utf8').catch(e=>{if(e.code==='ENOENT')return '';throw e;});const next=patch(old);if(old===next)continue;if(old){const backup=await contained(directory,'.boralances/design-backup-1.8.3/'+name);await fs.mkdir(path.dirname(backup),{recursive:true});await fs.writeFile(backup,old,{flag:'wx'}).catch(e=>{if(e.code!=='EEXIST')throw e;});}await fs.mkdir(path.dirname(file),{recursive:true});const temp=file+'.boralances-title.tmp';await fs.writeFile(temp,next);await fs.rename(temp,file);}await atomicJSON(marker,{version:'1.8.3',essentialMenu:'off',essentialServicesChanged:false,modMenuButton:'classic'});}
module.exports={patchEssential,sync};
